/* GridCraft PWA service worker.
 *
 * Generated by .github/workflows/publish-web.yml: the build fills in the real hashed asset
 * names trunk emitted and their SHA-256 integrity hashes.
 *
 * Strategy:
 *  - Precache everything the app needs on first load: index.html (network-first), the hashed
 *    wasm-bindgen JS + wasm bundle (cache-first — content-hashed, immutable), the offline
 *    fallback page and the manifest icons.
 *  - sw.js itself is byte-different on every publish (the build stamp contains its own hash),
 *    so the browser detects the new version, and clientsClaim + skipWaiting make it active
 *    immediately. The next load of index.html then comes network-first from the new build.
 */

const VERSION = 'gridcraft-@BUILD_STAMP@';
const APP_SHELL = [
  './',
  './index.html',
  './offline.html',
  './manifest.webmanifest',
];

// The hashed app bundle, precached with its exact integrity hash.
const JS = './@JS_FILE@';
const JS_INTEGRITY = 'sha256-@JS_SHA256@';
const WASM = './@WASM_FILE@';
const WASM_INTEGRITY = 'sha256-@WASM_SHA256@';

self.addEventListener('install', (event) => {
  event.waitUntil(
    (async () => {
      const cache = await caches.open(VERSION);
      // App shell + bundle: hard failures abort the install (a half-cached offline app is worse).
      await Promise.all([
        ...APP_SHELL.map((url) => cache.add(new Request(url, { cache: 'reload' }))),
        fetch(new Request(JS, { integrity: JS_INTEGRITY, cache: 'reload' }))
          .then((r) => cache.put(JS, r)),
        fetch(new Request(WASM, { integrity: WASM_INTEGRITY, cache: 'reload' }))
          .then((r) => cache.put(WASM, r)),
      ]);
      await self.skipWaiting();
    })(),
  );
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    (async () => {
      // Drop every cache from previous builds; the new one carries new hashed names anyway.
      const names = await caches.keys();
      await Promise.all(
        names.filter((n) => n !== VERSION).map((n) => caches.delete(n)),
      );
      await self.clients.claim();
    })(),
  );
});

self.addEventListener('fetch', (event) => {
  const url = new URL(event.request.url);
  const scope = new URL(self.registration.scope);

  // Same-origin, same-scope GETs only; the app talks to nothing else at runtime.
  if (event.request.method !== 'GET' || url.origin !== scope.origin) return;
  if (!url.pathname.startsWith(scope.pathname)) return;
  // Never cache or serve the service worker itself through this handler.
  if (url.pathname.endsWith('/sw.js')) return;

  // Navigations (index.html / offline.html): network first, offline fallback to the cached
  // shell — a stale app beats no app when the user is offline.
  if (event.request.mode === 'navigate') {
    event.respondWith(
      (async () => {
        try {
          const fresh = await fetch(event.request);
          const cache = await caches.open(VERSION);
          cache.put('./index.html', fresh.clone());
          return fresh;
        } catch {
          const cache = await caches.open(VERSION);
          return (
            (await cache.match('./index.html')) ||
            (await cache.match('./offline.html')) ||
            new Response('Offline', { status: 503, headers: { 'Content-Type': 'text/plain' } })
          );
        }
      })(),
    );
    return;
  }

  // Everything else (hashed wasm/js, icons, manifest): cache first. Hashed names never change
  // content, so once cached there is nothing newer to fetch.
  event.respondWith(
    (async () => {
      const cached = await caches.match(event.request, { ignoreVary: true });
      if (cached) return cached;
      try {
        const fresh = await fetch(event.request);
        if (fresh.ok) {
          const cache = await caches.open(VERSION);
          cache.put(event.request, fresh.clone());
        }
        return fresh;
      } catch {
        return new Response('Offline', { status: 503 });
      }
    })(),
  );
});
